// bun's console output, as the bun client's own tests pinned it, and the bun
// client's own reading of each — the oracle the board's reading of bun's
// console must equal.
//
// PROVENANCE. Every capture below is copied byte for byte from the bun
// client's tests, so the board's port is fed exactly what the client was:
//  - the verbatim `bun test` 1.3.14 (0d9b296a) captures, in both wire forms
//    (plain `(fail)` result lines and the ANSI-colourised `✗` form bun writes
//    even through a pipe), from the python module under tests/client/ that
//    pins which leaf a failure detail names, and the plain real capture
//    REAL_LEAKED_ASYNC_ERROR_LOG_PLAIN from its sibling module that pins
//    console failure attribution;
//  - the synthetic result-line fixtures that sibling builds with its
//    `_fail_line` / `_pass_line` / `_skip_line` / `_error_block` helpers;
//  - the frozen console streams of tests/clients-bun-crucible.test.ts
//    (FROZEN_STREAM_TIMEOUT_DETAIL_AFTER_FAIL, ..._BEFORE_FAIL,
//    FROZEN_STREAM_AFTERMATH_BLEED), with the scratch directory in their `at`
//    lines normalised to /tmp/bun-fixture/ as the other captures already were
//    (the reading never looks at it);
//  - two shapes the client's rules document but no client test pinned: a
//    second `error:` under one echo window, and a detail longer than the
//    message (1000) and trace (8000) cuts.
//
// CLIENT_READING is `_parse_console_failures` (clients/bun-crucible.py) run
// over each capture, keyed "<capture>/<wire>": for every married block, the
// composed result-line name AND its last " > " segment, each mapped to
// {message, trace}. It was computed once, from the client as it stands, and
// is frozen here so the port is held to the client's rules after the client
// stops reading the console.

export type WireForm = "plain" | "ansi";

/** A capture in its plain wire form, and its ANSI twin where one was captured. */
export interface Capture {
  plain: string;
  ansi?: string;
}

/** One block of console detail, married to a result-line name. */
export interface ConsoleDetail {
  message: string;
  trace?: string;
}


